gt_cones_body.sourceCode:
// GT cones transformed into base_link for BEV perception debug.
// Blue cubes = sim ground truth; compare against magenta /Conos_raw.
// Matches benchmark GT gate: 0.5–20 m radial, ±60° H-FOV (sim LiDAR MinRange + perception).

import { Input } from "./types";

type Marker = {
  header: { frame_id: string; stamp: { sec: number; nsec: number } };
  ns: string;
  id: number;
  type: number;
  action: number;
  pose: {
    position: { x: number; y: number; z: number };
    orientation: { x: number; y: number; z: number; w: number };
  };
  scale: { x: number; y: number; z: number };
  color: { r: number; g: number; b: number; a: number };
};

type MarkerArray = { markers: Marker[] };

const MIN_RANGE_M = 0.5;
const RANGE_M = 20.0;
const HFOV_HALF_DEG = 60.0;
const CUBE = 1;
const DELETEALL = 3;
const ADD = 0;

let latestTrack:
  | { track: Array<{ location: { x: number; y: number; z: number } }> }
  | undefined;
let latestOdom:
  | {
      header: { stamp: { sec: number; nsec: number } };
      pose: {
        pose: {
          position: { x: number; y: number };
          orientation: { w: number; x: number; y: number; z: number };
        };
      };
    }
  | undefined;

function quatYaw(q: { w: number; x: number; y: number; z: number }): number {
  return Math.atan2(
    2 * (q.w * q.z + q.x * q.y),
    1 - 2 * (q.y * q.y + q.z * q.z),
  );
}

function build(): MarkerArray | undefined {
  if (!latestTrack || !latestOdom) return undefined;
  const odom = latestOdom;
  const ox = odom.pose.pose.position.x;
  const oy = odom.pose.pose.position.y;
  const yaw = quatYaw(odom.pose.pose.orientation);
  const cosY = Math.cos(yaw);
  const sinY = Math.sin(yaw);
  const stamp = odom.header.stamp;
  const markers: Marker[] = [];
  let id = 0;
  markers.push({
    header: { frame_id: "base_link", stamp },
    ns: "gt",
    id: id++,
    type: CUBE,
    action: DELETEALL,
    pose: {
      position: { x: 0, y: 0, z: 0 },
      orientation: { x: 0, y: 0, z: 0, w: 1 },
    },
    scale: { x: 0.01, y: 0.01, z: 0.01 },
    color: { r: 0, g: 0, b: 0, a: 0 },
  });
  for (const cone of latestTrack.track) {
    const dx = cone.location.x - ox;
    const dy = cone.location.y - oy;
    const x = cosY * dx + sinY * dy;
    const y = -sinY * dx + cosY * dy;
    const r = Math.hypot(x, y);
    if (r < MIN_RANGE_M || r > RANGE_M) continue;
    if (x <= 0) continue;
    if (Math.abs(Math.atan2(y, x)) > (HFOV_HALF_DEG * Math.PI) / 180) continue;
    markers.push({
      header: { frame_id: "base_link", stamp },
      ns: "gt",
      id: id++,
      type: CUBE,
      action: ADD,
      pose: {
        position: { x, y, z: 0.15 },
        orientation: { x: 0, y: 0, z: 0, w: 1 },
      },
      scale: { x: 0.24, y: 0.24, z: 0.35 },
      color: { r: 0.15, g: 0.55, b: 1.0, a: 0.85 },
    });
  }
  return { markers };
}

export const inputs = ["/testing_only/track", "/testing_only/odom"];
export const output = "/studio_script/gt_cones_body";

export default function node(
  event: Input<"/testing_only/track"> | Input<"/testing_only/odom">,
): MarkerArray | undefined {
  if (event.topic === "/testing_only/track") {
    latestTrack = event.message;
  } else {
    latestOdom = event.message;
  }
  return build();
}

gt_cones_odom.sourceCode:
// Full GT track in odom/world frame (all cones, not range-gated).

import { Input } from "./types";

type Marker = {
  header: { frame_id: string; stamp: { sec: number; nsec: number } };
  ns: string;
  id: number;
  type: number;
  action: number;
  pose: {
    position: { x: number; y: number; z: number };
    orientation: { x: number; y: number; z: number; w: number };
  };
  scale: { x: number; y: number; z: number };
  color: { r: number; g: number; b: number; a: number };
};

type MarkerArray = { markers: Marker[] };

const CUBE = 1;
const DELETEALL = 3;
const ADD = 0;

function coneColor(
  color: number,
): { r: number; g: number; b: number; a: number } {
  if (color === 0) return { r: 1.0, g: 0.85, b: 0.0, a: 0.9 };
  if (color === 1) return { r: 0.2, g: 0.45, b: 1.0, a: 0.9 };
  if (color === 2) return { r: 1.0, g: 0.45, b: 0.0, a: 0.9 };
  return { r: 0.7, g: 0.7, b: 0.7, a: 0.7 };
}

export const inputs = ["/testing_only/track"];
export const output = "/studio_script/gt_cones_odom";

export default function node(
  event: Input<"/testing_only/track">,
): MarkerArray | undefined {
  const track = event.message;
  const stamp = event.receiveTime;
  const markers: Marker[] = [];
  let id = 0;
  markers.push({
    header: { frame_id: "odom", stamp },
    ns: "gt_track",
    id: id++,
    type: CUBE,
    action: DELETEALL,
    pose: {
      position: { x: 0, y: 0, z: 0 },
      orientation: { x: 0, y: 0, z: 0, w: 1 },
    },
    scale: { x: 0.01, y: 0.01, z: 0.01 },
    color: { r: 0, g: 0, b: 0, a: 0 },
  });
  for (const cone of track.track) {
    const c = coneColor(cone.color);
    markers.push({
      header: { frame_id: "odom", stamp },
      ns: "gt_track",
      id: id++,
      type: CUBE,
      action: ADD,
      pose: {
        position: {
          x: cone.location.x,
          y: cone.location.y,
          z: cone.location.z,
        },
        orientation: { x: 0, y: 0, z: 0, w: 1 },
      },
      scale: { x: 0.24, y: 0.24, z: 0.35 },
      color: c,
    });
  }
  return { markers };
}

gt_cone_count_fov.sourceCode:
// GT cone count in LiDAR-visible zone (0.5–20 m, ±60° H-FOV).

import { Input } from "./types";

type Output = { data: number };

const MIN_RANGE_M = 0.5;
const RANGE_M = 20.0;
const HFOV_HALF_DEG = 60.0;

let latestTrack:
  | { track: Array<{ location: { x: number; y: number } }> }
  | undefined;
let latestOdom:
  | {
      pose: {
        pose: {
          position: { x: number; y: number };
          orientation: { w: number; x: number; y: number; z: number };
        };
      };
    }
  | undefined;

function quatYaw(q: { w: number; x: number; y: number; z: number }): number {
  return Math.atan2(
    2 * (q.w * q.z + q.x * q.y),
    1 - 2 * (q.y * q.y + q.z * q.z),
  );
}

function countInFov(): number | undefined {
  if (!latestTrack || !latestOdom) return undefined;
  const ox = latestOdom.pose.pose.position.x;
  const oy = latestOdom.pose.pose.position.y;
  const yaw = quatYaw(latestOdom.pose.pose.orientation);
  const cosY = Math.cos(yaw);
  const sinY = Math.sin(yaw);
  let n = 0;
  for (const cone of latestTrack.track) {
    const dx = cone.location.x - ox;
    const dy = cone.location.y - oy;
    const x = cosY * dx + sinY * dy;
    const y = -sinY * dx + cosY * dy;
    const r = Math.hypot(x, y);
    if (r >= MIN_RANGE_M && r <= RANGE_M && x > 0 && Math.abs(Math.atan2(y, x)) <= (HFOV_HALF_DEG * Math.PI) / 180) n++;
  }
  return n;
}

export const inputs = ["/testing_only/track", "/testing_only/odom"];
export const output = "/studio_script/gt_cone_count_fov";

export default function node(
  event: Input<"/testing_only/track"> | Input<"/testing_only/odom">,
): Output | undefined {
  if (event.topic === "/testing_only/track") {
    latestTrack = event.message;
  } else {
    latestOdom = event.message;
  }
  const n = countInFov();
  if (n === undefined) return undefined;
  return { data: n };
}

perc_detected_count.sourceCode:
// Per-scan cone count from /Conos_raw (excludes DELETEALL marker).

import { Input } from "./types";

type Output = { data: number };

const ADD = 0;

export const inputs = ["/Conos_raw"];
export const output = "/studio_script/perc_detected_count";

export default function node(
  event: Input<"/Conos_raw">,
): Output | undefined {
  let n = 0;
  for (const m of event.message.markers) {
    if (m.action === ADD) n++;
  }
  return { data: n };
}

