recon_paths.sourceCode:
// Reconstructed trajectories: SLAM (blue) vs EKF /odom (red) vs GT (green).
//
// Three accumulated LINE_STRIPs in one MarkerArray, drawn in the `odom`
// render frame using raw positions - the same world-as-odom convention the
// dashboard already uses (Plot!pose_drift, gt_cones_odom). Divergence of the
// red EKF line from blue SLAM / green GT is accumulated dead-reckoning drift;
// divergence of blue from green is residual SLAM error.
//
// AUTO-REFRESH: the trails clear themselves when a new run starts, so no stale
// data carries over on a live stream. A reset is detected when either
//   (a) the message stamp jumps backwards (sim /clock restarted / replay loop), or
//   (b) the pose teleports (car snapped back to the start gate).
// To wipe everything manually instead, reconnect the data source in Lichtblick.
//
// Output: /studio_script/recon_paths (visualization_msgs/MarkerArray).

import { Input } from "./types";

type Point = { x: number; y: number; z: number };
type RGBA = { r: number; g: number; b: number; a: number };
type Marker = {
  header: { frame_id: string; stamp: { sec: number; nsec: number } };
  ns: string; id: number; type: number; action: number;
  pose: { position: Point; orientation: { x: number; y: number; z: number; w: number } };
  scale: Point; color: RGBA; points: Point[];
};
type MarkerArray = { markers: Marker[] };

const LINE_STRIP = 4;
const ADD = 0;
const MAX_PTS = 6000;
const STAMP_REWIND_S = 0.5; // stamp going back this far => new run
const TELEPORT_M = 10.0;    // jump this far between samples => reset

export const inputs = ["/slam/pose", "/odom", "/testing_only/odom"];
export const output = "/studio_script/recon_paths";

const slamPts: Point[] = [];
const ekfPts: Point[] = [];
const gtPts: Point[] = [];
const lastPos: { [topic: string]: Point } = {};
let maxStamp = -1;
let lastStamp = { sec: 0, nsec: 0 };

function toSec(s: { sec: number; nsec: number }): number {
  return s.sec + s.nsec * 1e-9;
}

function clearAll(): void {
  slamPts.length = 0;
  ekfPts.length = 0;
  gtPts.length = 0;
  for (const k of Object.keys(lastPos)) delete lastPos[k];
}

function push(arr: Point[], p: Point): void {
  arr.push({ x: p.x, y: p.y, z: 0.05 });
  if (arr.length > MAX_PTS) arr.shift();
}

function line(id: number, pts: Point[], color: RGBA): Marker {
  return {
    header: { frame_id: "odom", stamp: lastStamp },
    ns: "recon_paths", id, type: LINE_STRIP, action: ADD,
    pose: { position: { x: 0, y: 0, z: 0 }, orientation: { x: 0, y: 0, z: 0, w: 1 } },
    scale: { x: 0.15, y: 0, z: 0 },
    color, points: pts.map((q) => ({ x: q.x, y: q.y, z: q.z })),
  };
}

export default function node(
  event: Input<"/slam/pose"> | Input<"/odom"> | Input<"/testing_only/odom">,
): MarkerArray | undefined {
  const stamp = event.message.header.stamp;
  const t = toSec(stamp);
  const p = event.message.pose.pose.position;

  // (a) clock rewound -> new run / replay loop.
  if (maxStamp >= 0 && t < maxStamp - STAMP_REWIND_S) clearAll();
  if (t > maxStamp) maxStamp = t;

  // (b) teleport on this stream -> car snapped back to start.
  const prev = lastPos[event.topic];
  if (prev !== undefined && Math.hypot(p.x - prev.x, p.y - prev.y) > TELEPORT_M) {
    clearAll();
  }
  lastPos[event.topic] = { x: p.x, y: p.y, z: 0 };
  lastStamp = stamp;

  if (event.topic === "/slam/pose") push(slamPts, p);
  else if (event.topic === "/odom") push(ekfPts, p);
  else push(gtPts, p);

  const markers: Marker[] = [];
  if (slamPts.length > 1) markers.push(line(0, slamPts, { r: 0.27, g: 0.53, b: 1.0, a: 0.95 }));
  if (ekfPts.length > 1) markers.push(line(1, ekfPts, { r: 1.0, g: 0.27, b: 0.27, a: 0.95 }));
  if (gtPts.length > 1) markers.push(line(2, gtPts, { r: 0.27, g: 0.87, b: 0.53, a: 0.95 }));
  return { markers };
}

map_to_odom_norm.sourceCode:
// ||map -> odom|| translation magnitude from /tf.
//
// `map -> odom` is SLAM's drift-correction transform: how far it has had to
// drag the odom frame to keep dead-reckoning agreeing with the cone map. A
// healthy lap stays sub-metre; tens of metres means dead-reckoning is the
// upstream problem.
//
// Output: /studio_script/map_to_odom_norm (m, Float32-shaped).

import { Input } from "./types";

type Output = { data: number };

export const inputs = ["/tf"];
export const output = "/studio_script/map_to_odom_norm";

export default function node(event: Input<"/tf">): Output | undefined {
  for (const t of event.message.transforms) {
    if (t.header.frame_id === "map" && t.child_frame_id === "odom") {
      const tx = t.transform.translation.x;
      const ty = t.transform.translation.y;
      return { data: Math.hypot(tx, ty) };
    }
  }
  return undefined;
}

gt_pose_point.sourceCode:
// Current GT car position (/testing_only/odom) as a single sphere, drawn in
// the odom render frame with the raw position - the same world-as-odom
// convention as recon_paths. Bright green = ground-truth "now".
//
// Diagnostic intent: compare this sphere against the /Path near end and the
// SLAM/EKF trails. If GT sits AHEAD of the path's first waypoints, the path
// is lagging the real car (live transport delay) - the failure under
// investigation. On a straight the gap is invisible; at a corner it spikes.
//
// Output: /studio_script/gt_pose_point (visualization_msgs/MarkerArray).

import { Input } from "./types";

type Pt = { x: number; y: number; z: number };
type Marker = {
  header: { frame_id: string; stamp: { sec: number; nsec: number } };
  ns: string; id: number; type: number; action: number;
  pose: { position: Pt; orientation: { x: number; y: number; z: number; w: number } };
  scale: Pt; color: { r: number; g: number; b: number; a: number };
};
type MarkerArray = { markers: Marker[] };

const SPHERE = 2;
const ADD = 0;

export const inputs = ["/testing_only/odom"];
export const output = "/studio_script/gt_pose_point";

export default function node(
  event: Input<"/testing_only/odom">,
): MarkerArray {
  const p = event.message.pose.pose.position;
  const stamp = event.message.header.stamp;
  return {
    markers: [
      {
        header: { frame_id: "odom", stamp },
        ns: "gt_pose",
        id: 0,
        type: SPHERE,
        action: ADD,
        pose: {
          position: { x: p.x, y: p.y, z: 0.3 },
          orientation: { x: 0, y: 0, z: 0, w: 1 },
        },
        scale: { x: 0.6, y: 0.6, z: 0.6 },
        color: { r: 0.1, g: 1.0, b: 0.3, a: 1.0 },
      },
    ],
  };
}
